"""Renal topics for internal medicine: electrolytes / acid-base and glomerular diseases (Harrison 22e kidney chapters)."""
from common import Topic

SRC = "Harrison 22e"
ELY = "אלקטרוליטים וחומצה-בסיס"
GLO = "מחלות גלומרולריות"


def topics():
    T = []

    t = Topic("hna", "היפרנתרמיה ו-Diabetes Insipidus", "Hypernatremia & Diabetes Insipidus", ELY, SRC, """
<h4>רקע</h4><ul><li>נתרן מעל 145 mEq/L. כמעט תמיד חוסר במים חופשיים ביחס לנתרן, בדרך כלל אצל מי שאין לו גישה למים או מנגנון צמא תקין (קשישים, תינוקות, ירידה בהכרה).</li></ul>
<h4>סיבות</h4><ul><li>איבוד מים חוץ-כלייתי: הזעה, שלשול אוסמוטי, נשימה. שתן מרוכז מאוד (מעל 800 mOsm/kg).</li><li>איבוד כלייתי: DI מרכזי או נפרוגני, דיורזה אוסמוטית (גלוקוז, אוריאה, מניטול).</li><li>DI: פוליאוריה מעל 3 ליטר ביום עם שתן מהול (מתחת ל-300 mOsm/kg).</li><li>DI מרכזי: ניתוח/טראומה, גידולים (קרניופרינגיומה), מחלות חודרניות, אידיופתי.</li><li>DI נפרוגני: ליתיום (השכיח בבוגרים), היפרקלצמיה, היפוקלמיה, גנטי (קולטן V2, AQP2).</li></ul>
<h4>אבחנה מבדלת של DI</h4><ul><li>מבחן צום מים ואחריו דזמופרסין: במרכזי, אוסמולריות השתן עולה במעל 50% אחרי דזמופרסין. בנפרוגני כמעט אין עלייה.</li><li>Copeptin (מקביל ל-ADH) מחליף היום את מבחן הצום: גבוה בבסיס ב-DI נפרוגני, ונמוך אחרי גירוי ב-DI מרכזי.</li></ul>
<h4>טיפול</h4><ul><li>חוסר מים חופשיים = TBW × (Na/140 − 1). TBW: 0.6 × משקל בגבר צעיר, 0.5 באישה ובגבר מבוגר, 0.45 באישה מבוגרת.</li><li>היפרנתרמיה כרונית (מעל 48 שעות): תיקון של עד 10 mEq/L ב-24 שעות, אחרת יש סכנת בצקת מוחית.</li><li>DI מרכזי: דזמופרסין. DI נפרוגני: דיאטה דלת מלח וחלבון, תיאזיד, NSAIDs, אמילוריד בליתיום.</li></ul>
""", ["hypernatremia", "DI", "desmopressin"])
    t.N("מהי מגבלת התיקון של היפרנתרמיה כרונית ב-24 שעות?", 10, 0, "mEq/L")
    t.F("מהי הנוסחה לחישוב חוסר מים חופשיים?", "TBW × (Na/140 − 1). TBW: 0.6 × משקל בגבר צעיר, 0.5 באישה ובגבר מבוגר, 0.45 באישה מבוגרת.")
    t.N("גבר בן 40, 70 ק״ג, נתרן 154. כמה ליטרים של מים חופשיים חסרים לו?", 4.2, 0.1, "ליטר", "0.6 × 70 = 42 ליטר TBW. 42 × (154/140 − 1) = 42 × 0.1 = 4.2 ליטר.")
    t.M("מהי הסיבה השכיחה ביותר ל-DI נפרוגני נרכש במבוגרים?", ["היפרקלצמיה", "ליתיום", "היפוקלמיה", "אמילואידוזיס"], 1)
    t.F("במבחן צום מים, איך מבדילים בין DI מרכזי לנפרוגני?", "נותנים דזמופרסין בסוף הצום. ב-DI מרכזי אוסמולריות השתן עולה במעל 50%. ב-DI נפרוגני כמעט אין שינוי.")
    t.N("מעל כמה ליטרים של שתן ביום מוגדרת פוליאוריה?", 3, 0, "ליטר")
    t.M("איזו תרופה משמשת לטיפול ב-DI נפרוגני שנגרם מליתיום?", ["דזמופרסין", "אמילוריד", "פורוסמיד", "ספירונולקטון"], 1, "אמילוריד חוסם את ENaC, שדרכו ליתיום נכנס לתאי צינור המאסף.")
    t.F("מהם 2 הסיבוכים המטבוליים שגורמים ל-DI נפרוגני?", "היפרקלצמיה והיפוקלמיה.")
    T.append(t)

    t = Topic("hypok", "היפוקלמיה", "Hypokalemia", ELY, SRC, """
<h4>סיבות</h4><ul><li>מעבר לתוך התאים: אינסולין, בטא-אגוניסטים, אלקלוזיס, שיתוק תקופתי היפוקלמי (תירוטוקסיקוזיס).</li><li>איבוד חוץ-כלייתי: שלשולים (עם חמצת מטבולית). K בשתן מתחת ל-15 mmol ליום.</li><li>איבוד כלייתי: משתנים (השכיח), הקאות (האיבוד הוא כלייתי, דרך ביקרבונטוריה ואלדוסטרון משני), עודף מינרלוקורטיקואידים, Bartter, Gitelman, Liddle, RTA טיפוס 1 ו-2, היפומגנזמיה, אמפוטריצין.</li></ul>
<h4>עם יתר לחץ דם: לפי רנין ואלדוסטרון</h4><ul><li>רנין נמוך ואלדוסטרון גבוה: היפראלדוסטרוניזם ראשוני (Conn).</li><li>שניהם גבוהים: היצרות עורק כלייתי, גידול מפריש רנין.</li><li>שניהם נמוכים: Liddle, ליקוריץ, Cushing, CAH (11β-hydroxylase).</li></ul>
<h4>ללא יתר לחץ דם, עם בססת</h4><ul><li>Bartter: כמו משתן לולאה, היפרקלציאוריה, ילדים.</li><li>Gitelman: כמו תיאזיד, היפוקלציאוריה והיפומגנזמיה, מבוגרים צעירים.</li></ul>
<h4>קליניקה</h4><ul><li>חולשת שרירים, ileus, רבדומיוליזיס, DI נפרוגני, הפרעות קצב (בעיקר עם דיגוקסין).</li><li>אק״ג: גלי U, T שטוחים, שקיעת ST, הארכת QT.</li></ul>
<h4>טיפול</h4><ul><li>KCl פומי עדיף. ירידה של 1 mEq/L (מ-4 ל-3) משקפת חוסר של כ-200-400 mEq.</li><li>תוך-ורידי: עד כ-10 mEq/h בווריד פריפרי (עד 20 mEq/h בווריד מרכזי עם ניטור).</li><li>לתקן קודם היפומגנזמיה, אחרת האיבוד הכלייתי נמשך.</li><li>לא לתת בתמיסה עם גלוקוז, שמגבירה הפרשת אינסולין.</li></ul>
""", ["hypokalemia", "Bartter", "Gitelman", "Liddle"])
    t.F("מהם ממצאי האק״ג בהיפוקלמיה?", "גלי U, השטחת גלי T, שקיעת ST, הארכת QT (QU).")
    t.M("מה מבדיל בין Gitelman ל-Bartter?", ["ב-Gitelman יש יתר לחץ דם", "ב-Gitelman יש היפוקלציאוריה והיפומגנזמיה", "ב-Bartter יש חמצת", "ב-Bartter רנין נמוך"], 1)
    t.F("היפוקלמיה, יתר לחץ דם, רנין נמוך ואלדוסטרון גבוה. מה האבחנה?", "היפראלדוסטרוניזם ראשוני (Conn).")
    t.F("היפוקלמיה, יתר לחץ דם, רנין נמוך ואלדוסטרון נמוך. מה האבחנה המבדלת?", "Liddle (ENaC פעיל מדי), צריכת ליקוריץ (עיכוב 11β-HSD2), Cushing, CAH של 11β-hydroxylase או 17α-hydroxylase.")
    t.F("איזה ליקוי אלקטרוליטי חייבים לתקן לפני שהיפוקלמיה תתוקן?", "היפומגנזמיה.")
    t.N("מהו קצב המתן המקסימלי המקובל של KCl בווריד פריפרי?", 10, 0, "mEq/h")
    t.M("מטופל מקיא שבוע. מהו המנגנון העיקרי להיפוקלמיה?", ["איבוד K בהקאות", "איבוד כלייתי עקב ביקרבונטוריה ואלדוסטרון משני", "מעבר לתוך התאים", "חוסר צריכה"], 1, "תוכן הקיבה דל ב-K. האיבוד העיקרי הוא בשתן.")
    t.N("חוסר משוער (mEq) של K כשרמתו יורדת מ-4 ל-3 (ערך מרכזי)?", 300, 100, "mEq", "בערך 200-400 mEq.")
    T.append(t)

    t = Topic("hyperk", "היפרקלמיה", "Hyperkalemia", ELY, SRC, """
<h4>סיבות</h4><ul><li>פסאודו-היפרקלמיה: המוליזה בדגימה, טרומבוציטוזיס, לויקוציטוזיס קיצונית, קפיצת אגרוף.</li><li>מעבר מהתאים: חמצת, חוסר אינסולין, היפראוסמולריות, בטא-חוסמים, דיגוקסין, סוקצינילכולין, פירוק רקמות (תסמונת פירוק גידול, רבדומיוליזיס).</li><li>הפרשה כלייתית ירודה: AKI/CKD, היפואלדוסטרוניזם (Addison, RTA טיפוס 4), תרופות: ACEi/ARB, MRA, אמילוריד, טרימתופרים, הפרין, קלציניורין, NSAIDs.</li></ul>
<h4>אק״ג (בסדר ההחמרה)</h4><ul><li>גלי T מחודדים, אחר כך הארכת PR והשטחת P, הרחבת QRS, ובסוף sine wave ו-VF או אסיסטולה.</li><li>אק״ג תקין לא שולל סכנה.</li></ul>
<h4>טיפול חירום</h4><ul><li>ייצוב ממברנה: קלציום גלוקונט 10%, 10 mL במשך 2-3 דקות. השפעה תוך דקות, לחזור אם האק״ג לא משתפר.</li><li>הזזה לתוך התאים: אינסולין רגיל 10 יחידות IV עם 25 גרם גלוקוז (השפעה תוך 10-20 דקות, מוריד כ-0.6-1 mEq/L). אלבוטרול 10-20 מ״ג באינהלציה. ביקרבונט רק בחמצת.</li><li>הוצאה מהגוף: משתני לולאה, קושרים (Patiromer, Sodium zirconium cyclosilicate), דיאליזה.</li></ul>
""", ["hyperkalemia", "calcium gluconate"])
    t.F("תאר את רצף שינויי האק״ג בהיפרקלמיה.", "T מחודדים, הארכת PR והשטחת P, הרחבת QRS, sine wave, ואז VF או אסיסטולה.")
    t.M("מה הצעד הראשון במטופל עם K של 7.2 ו-QRS רחב?", ["אינסולין וגלוקוז", "קלציום גלוקונט IV", "פורוסמיד", "קושר אשלגן"], 1, "קלציום מייצב את ממברנת שריר הלב ולא מוריד את רמת ה-K.")
    t.N("כמה יחידות אינסולין רגיל ניתנות IV בטיפול בהיפרקלמיה?", 10, 0, "יחידות")
    t.M("איזו אנטיביוטיקה גורמת להיפרקלמיה במנגנון דמוי אמילוריד?", ["אמוקסיצילין", "טרימתופרים", "ציפרופלוקסצין", "דוקסיציקלין"], 1)
    t.F("מה גורם לפסאודו-היפרקלמיה?", "המוליזה בדגימה, טרומבוציטוזיס, לויקוציטוזיס קיצונית (למשל CLL), קפיצת אגרוף או חסם עורקים ממושך.")
    t.F("מהן 3 דרכי הפעולה בטיפול בהיפרקלמיה, עם דוגמה לכל אחת?", "ייצוב ממברנה: קלציום. הכנסה לתאים: אינסולין עם גלוקוז, אלבוטרול. הוצאה מהגוף: משתני לולאה, קושרים (Patiromer, SZC), דיאליזה.")
    t.F("איזה סוג RTA מתבטא בהיפרקלמיה, ומהו המצב הקליני הקלאסי שלו?", "RTA טיפוס 4 (היפואלדוסטרוניזם היפורנינמי), קלאסית בסוכרתיים עם CKD קלה עד בינונית.")
    T.append(t)

    t = Topic("macid", "חמצת מטבולית", "Metabolic Acidosis", ELY, SRC, """
<h4>גישה</h4><ul><li>פער אניוני (AG) = Na − (Cl + HCO3). תקין כ-10-12.</li><li>תיקון לאלבומין: AG עולה ב-2.5 לכל ירידה של 1 g/dL באלבומין מתחת ל-4.</li><li>פיצוי צפוי (Winter): PaCO2 = 1.5 × HCO3 + 8 (±2). ערך גבוה יותר מצביע על חמצת נשימתית נוספת.</li><li>Delta/delta = ΔAG / ΔHCO3. מעל 2: בססת מטבולית נוספת. מתחת ל-1: חמצת עם AG תקין נוספת.</li></ul>
<h4>AG מוגבר (GOLDMARK)</h4><ul><li>Glycols (אתילן ופרופילן), Oxoproline (פרצטמול כרוני), L-lactate, D-lactate, Methanol, Aspirin, Renal failure, Ketoacidosis.</li><li>פער אוסמולרי מעל 10: חשד לאלכוהולים רעילים. מתנול: הפרעות ראייה. אתילן גליקול: גבישי אוקסלט ו-AKI. טיפול: פומפיזול ודיאליזה.</li><li>סליצילטים: בססת נשימתית יחד עם חמצת מטבולית עם AG מוגבר.</li></ul>
<h4>AG תקין (היפרכלורמית)</h4><ul><li>שלשול, RTA, מתן NaCl בכמות גדולה, אצטזולאמיד, uretero-sigmoidostomy.</li><li>פער אניוני בשתן = Na + K − Cl. שלילי: איבוד במערכת העיכול (הפרשת NH4 תקינה). חיובי: RTA.</li></ul>
""", ["anion gap", "Winter", "osmolal gap", "GOLDMARK"])
    t.F("מהי נוסחת Winter ולמה היא משמשת?", "PaCO2 צפוי = 1.5 × HCO3 + 8 (±2). בודקת אם הפיצוי הנשימתי לחמצת מטבולית מתאים.")
    t.N("HCO3 של 12. מהו ה-PaCO2 הצפוי לפי Winter?", 26, 2, "mmHg", "1.5 × 12 + 8 = 26 (±2).")
    t.N("Na 140, Cl 100, HCO3 14. מהו הפער האניוני?", 26, 0, "")
    t.N("בכמה עולה ה-AG המתוקן לכל ירידה של 1 g/dL באלבומין?", 2.5, 0, "")
    t.F("מה פירוש פער אניוני שלילי בשתן בחולה עם חמצת היפרכלורמית?", "הפרשת NH4 תקינה, ולכן סביר שמקור החמצת הוא איבוד ביקרבונט במערכת העיכול (שלשול). פער חיובי מרמז על RTA.")
    t.M("חולה עם חמצת עם AG מוגבר, פער אוסמולרי גבוה, גבישי אוקסלט בשתן ו-AKI. מה הגורם?", ["מתנול", "אתילן גליקול", "סליצילטים", "קטואצידוזיס אלכוהולית"], 1)
    t.F("מה מראה delta/delta מעל 2 בחמצת עם AG מוגבר?", "בססת מטבולית נוספת (HCO3 גבוה מהצפוי). מתחת ל-1 מראה חמצת נוספת עם AG תקין.")
    t.M("מטופל עם בססת נשימתית וחמצת מטבולית עם AG מוגבר. מה החשד הקלאסי?", ["שלשול", "הרעלת סליצילטים", "DKA", "אי-ספיקת כליות"], 1)
    t.N("מעל איזה פער אוסמולרי (mOsm/kg) חושדים באלכוהול רעיל?", 10, 0, "mOsm/kg")
    T.append(t)

    t = Topic("malk", "בססת מטבולית", "Metabolic Alkalosis", ELY, SRC, """
<h4>פיצוי</h4><ul><li>PaCO2 עולה בכ-0.7 mmHg לכל עלייה של 1 mEq/L ב-HCO3.</li></ul>
<h4>חלוקה לפי כלוריד בשתן</h4><ul><li>כלוריד בשתן מתחת ל-20 (מגיבה למלח): הקאות או זונדה, משתנים בעבר, פוסט-היפרקפניה, ציסטיק פיברוזיס, אדנומה וילוסית.</li><li>כלוריד בשתן מעל 20 (לא מגיבה למלח): עם יתר לחץ דם: עודף מינרלוקורטיקואידים, Liddle. בלי יתר לחץ דם: משתנים בשימוש עכשווי, Bartter, Gitelman, היפוקלמיה חמורה.</li><li>בהקאות משתמשים בכלוריד ולא בנתרן בשתן, כי הביקרבונטוריה גוררת איתה נתרן.</li></ul>
<h4>גורמים שמשמרים את הבססת</h4><ul><li>חוסר נפח, חוסר כלוריד, היפוקלמיה, היפראלדוסטרוניזם.</li></ul>
<h4>טיפול</h4><ul><li>מגיבה למלח: NaCl ו-KCl. לא מגיבה: טיפול בגורם, ספירונולקטון. בעומס נוזלים: אצטזולאמיד.</li><li>Milk-alkali: סידן ובסיס פומיים, היפרקלצמיה ואי-ספיקת כליות.</li></ul>
""", ["metabolic alkalosis", "urine chloride"])
    t.N("בכמה mmHg עולה ה-PaCO2 בפיצוי לכל עלייה של 1 mEq/L ב-HCO3?", 0.7, 0, "mmHg")
